---@param cfg XTablePBRCharacter
function XUiPBRCharacterDetail:OnCharacterSelectChanged(cfg)
    -- 刷新
    self.PanelAttribute:RefreshStatusShow(cfg.CharacterId, true)
    self.PanelExclusive:RefreshCharacterExclusiveDesc(cfg.CharacterId, true)
    
    local isUnlock, lockDesc = self._Control.CharacterControl:GetIsCharacterUnlock(cfg.CharacterId)

    if not isUnlock then
        if self.ImgTipsBg then
