        end
        
        self.TxtTips.text = lockDesc
    else
        self.TxtTips.text = ''

        if self.ImgTipsBg then
            self.ImgTipsBg.gameObject:SetActiveEx(false)
        end
    end
    
    -- 切换模型，加载完成后播放 IdleAction（异步加载，须在 onLoaded 回调里播，避免 animator 未就绪失效）
